{
  "info": {
    "_postman_id": "8d7e8d2e-6d9e-4fd6-a4f4-8e7a7b4f9f71",
    "name": "PistaPadel API",
    "description": "Coleccion lista para importar. Orden recomendado: 1) Auth -> Register USER, 2) Auth -> Me (USER), 3) Courts -> List/Crear (ADMIN), 4) Reservations, 5) Availability, 6) Admin. Nota: /pistaPadel/auth/login no existe en el controlador actual; usa Basic Auth en cada request autenticada.",
    "schema": "https://schema.getpostman.com/json/collection/v2.1.0/collection.json"
  },
  "item": [
    {
      "name": "01 - Auth",
      "item": [
        {
          "name": "Register USER",
          "request": {
            "method": "POST",
            "header": [
              {
                "key": "Content-Type",
                "value": "application/json"
              }
            ],
            "url": {
              "raw": "{{baseUrl}}/pistaPadel/auth/register",
              "host": [
                "{{baseUrl}}"
              ],
              "path": [
                "pistaPadel",
                "auth",
                "register"
              ]
            },
            "body": {
              "mode": "raw",
              "raw": "{\n  \"nombre\": \"{{userNombre}}\",\n  \"apellidos\": \"{{userApellidos}}\",\n  \"email\": \"{{userEmail}}\",\n  \"password\": \"{{userPassword}}\",\n  \"telefono\": \"{{userTelefono}}\"\n}"
            },
            "description": "Registro publico de usuario normal. Si ya existe email devolvera 409."
          },
          "response": []
        },
        {
          "name": "Register ADMIN (opcional)",
          "request": {
            "method": "POST",
            "header": [
              {
                "key": "Content-Type",
                "value": "application/json"
              }
            ],
            "url": {
              "raw": "{{baseUrl}}/pistaPadel/auth/register",
              "host": [
                "{{baseUrl}}"
              ],
              "path": [
                "pistaPadel",
                "auth",
                "register"
              ]
            },
            "body": {
              "mode": "raw",
              "raw": "{\n  \"nombre\": \"{{adminNombre}}\",\n  \"apellidos\": \"{{adminApellidos}}\",\n  \"email\": \"{{adminEmail}}\",\n  \"password\": \"{{adminPassword}}\",\n  \"telefono\": \"{{adminTelefono}}\",\n  \"rol\": {\n    \"nombreRol\": \"ADMIN\"\n  }\n}"
            },
            "description": "Opcional, util si no tienes admin creado."
          },
          "response": []
        },
        {
          "name": "Me (USER)",
          "event": [
            {
              "listen": "test",
              "script": {
                "exec": [
                  "if (pm.response.code === 200) {",
                  "  var data = pm.response.json();",
                  "  if (data && data.id) { pm.environment.set('userId', data.id); }",
                  "}"
                ],
                "type": "text/javascript"
              }
            }
          ],
          "request": {
            "auth": {
              "type": "basic",
              "basic": [
                {
                  "key": "username",
                  "value": "{{userEmail}}",
                  "type": "string"
                },
                {
                  "key": "password",
                  "value": "{{userPassword}}",
                  "type": "string"
                }
              ]
